import { describe, it, expect } from 'vite-plus/test'

import { crc32, zipStream } from '../lib/zip.js'

// The stored-ZIP writer (ahaqqu/RumaQ#440 — ticket 6's dependency-free
// archive format). Every test parses the generated bytes with the
// hand-written reader below — the SAME round-trip discipline the export
// suite uses, so a malformed writer fails here at the unit level before it
// can fail an export. No third-party parser exists to lean on (the whole
// point is no new dependency), and the reader IS the validation: signatures,
// method 0, the UTF-8 flag, real sizes/CRC in local headers, and a central
// directory that lands exactly at the EOCD.

// RFC 1952's worked example — the pin that the CRC-32 table/shifts are the
// IEEE 802.3 parameters, not a lookalike.
it('crc32 matches the standard vector', () => {
  expect(crc32(new TextEncoder().encode('123456789'))).toBe(0xcbf43926)
})

type ParsedEntry = {
  name: string
  crc: number
  size: number
  bytes: Uint8Array
  dosTime: number
  dosDate: number
  flags: number
}

/**
 * Minimal ZIP reader: walks the central directory (the authoritative index)
 * and re-derives every entry's bytes from its LOCAL header position,
 * recomputing the CRC over what actually landed in the file. Throws on any
 * structural lie.
 */
function parseZip(bytes: Uint8Array): Map<string, ParsedEntry> {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
  let eocd = -1
  for (let i = bytes.length - 22; i >= 0; i--) {
    if (view.getUint32(i, true) === 0x06054b50) {
      eocd = i
      break
    }
  }
  if (eocd < 0) throw new Error('no EOCD record found')
  const total = view.getUint16(eocd + 10, true)
  const cdOffset = view.getUint32(eocd + 16, true)

  const entries = new Map<string, ParsedEntry>()
  let at = cdOffset
  for (let n = 0; n < total; n++) {
    if (view.getUint32(at, true) !== 0x02014b50) throw new Error('bad central directory signature')
    const flags = view.getUint16(at + 8, true)
    const method = view.getUint16(at + 10, true)
    const crc = view.getUint32(at + 16, true)
    const size = view.getUint32(at + 20, true)
    const nameLen = view.getUint16(at + 28, true)
    const extraLen = view.getUint16(at + 30, true)
    const commentLen = view.getUint16(at + 32, true)
    const localOffset = view.getUint32(at + 42, true)
    const name = new TextDecoder().decode(bytes.subarray(at + 46, at + 46 + nameLen))
    if (method !== 0) throw new Error(`entry ${name}: not stored (method ${method})`)
    if ((flags & 0x0800) !== 0x0800) throw new Error(`entry ${name}: UTF-8 flag not set`)

    if (view.getUint32(localOffset, true) !== 0x04034b50) {
      throw new Error(`entry ${name}: bad local header signature`)
    }
    const lfhNameLen = view.getUint16(localOffset + 26, true)
    const lfhExtraLen = view.getUint16(localOffset + 28, true)
    const dataStart = localOffset + 30 + lfhNameLen + lfhExtraLen
    const data = bytes.subarray(dataStart, dataStart + size)
    if (crc32(data) !== crc) throw new Error(`entry ${name}: CRC mismatch over extracted bytes`)

    entries.set(name, {
      name,
      crc,
      size,
      bytes: data,
      dosTime: view.getUint16(localOffset + 10, true),
      dosDate: view.getUint16(localOffset + 12, true),
      flags,
    })
    at += 46 + nameLen + extraLen + commentLen
  }
  if (at !== eocd) throw new Error('central directory does not end at the EOCD record')
  return entries
}

async function collect(entries: Parameters<typeof zipStream>[0]): Promise<Uint8Array> {
  const stream = zipStream(entries)
  const reader = stream.getReader()
  const chunks: Uint8Array[] = []
  let total = 0
  for (;;) {
    const { done, value } = await reader.read()
    if (done) break
    total += value.byteLength
    chunks.push(value)
  }
  const bytes = new Uint8Array(total)
  let at = 0
  for (const chunk of chunks) {
    bytes.set(chunk, at)
    at += chunk.byteLength
  }
  return bytes
}

describe('stored zip writer (ticket 6 #440)', () => {
  it('round-trips entries: names, bytes and sizes survive the archive', async () => {
    const payload = new TextEncoder().encode('isi dokumen, dengan koma & "quotes"\r\n')
    const bytes = await collect([
      { name: 'documents.csv', data: payload },
      { name: 'files/ktp.jpg', data: new Uint8Array([0xff, 0xd8, 0xff, 0xe0, 1, 2, 3]) },
    ])
    const entries = parseZip(bytes)
    expect(entries.size).toBe(2)
    expect([...entries.keys()].sort()).toEqual(['documents.csv', 'files/ktp.jpg'])
    expect(entries.get('documents.csv')?.size).toBe(payload.byteLength)
    expect([...entries.get('documents.csv')!.bytes]).toEqual([...payload])
    expect([...entries.get('files/ktp.jpg')!.bytes]).toEqual([0xff, 0xd8, 0xff, 0xe0, 1, 2, 3])
  })

  it('writes a valid empty archive (EOCD with zero entries)', async () => {
    const bytes = await collect([])
    expect(parseZip(bytes).size).toBe(0)
  })

  it('decodes non-ASCII names (UTF-8 flag round-trip)', async () => {
    const bytes = await collect([
      { name: 'files/d1/1-Dok KTP₂ & akta.pdf', data: new Uint8Array([1, 2]) },
    ])
    expect([...parseZip(bytes).keys()]).toEqual(['files/d1/1-Dok KTP₂ & akta.pdf'])
  })

  it('resolves lazy loaders as the stream pulls, in entry order', async () => {
    const order: string[] = []
    const bytes = await collect([
      {
        name: 'a',
        data: () => {
          order.push('a')
          return new Uint8Array([1])
        },
      },
      {
        name: 'b',
        data: async () => {
          order.push('b')
          return new Uint8Array([2, 2])
        },
      },
    ])
    expect(order).toEqual(['a', 'b'])
    expect(parseZip(bytes).get('b')?.size).toBe(2)
  })

  it('encodes the entry timestamp as a DOS date/time (UTC)', async () => {
    const modified = new Date(Date.UTC(2026, 10, 7, 9, 30, 20))
    const bytes = await collect([{ name: 'a', data: new Uint8Array([1]), modified }])
    const entry = parseZip(bytes).get('a')!
    expect(entry.dosDate).toBe(((2026 - 1980) << 9) | (11 << 5) | 7)
    expect(entry.dosTime).toBe((9 << 11) | (30 << 5) | 10) // 2-second resolution
  })

  it('cancels without pulling the remaining entries (aborted download stops storage reads)', async () => {
    const pulled: string[] = []
    const stream = zipStream([
      {
        name: 'a',
        data: () => {
          pulled.push('a')
          return new Uint8Array([1])
        },
      },
      {
        name: 'b',
        data: () => {
          pulled.push('b')
          return new Uint8Array([2])
        },
      },
    ])
    const reader = stream.getReader()
    await reader.read()
    await reader.cancel()
    await new Promise((resolve) => setTimeout(resolve, 0))
    expect(pulled).toEqual(['a'])
  })
})
